    "folia.releaseNotes.v0_5_27.intro": "以下是 0.5.27 版本的新功能与改进",
    "folia.releaseNotes.v0_5_27.diorama.title": "Diorama「镜台」3D 歌词模式",
    "folia.releaseNotes.v0_5_27.diorama.description":
      "歌词化作空间中的 3D 文字，镜头沿路径逐句飞行，并支持跟唱辉光、粒子与主题联动。",
    "folia.releaseNotes.v0_5_27.lyricOffsetMemory.title": "时间轴偏移保存",
    "folia.releaseNotes.v0_5_27.lyricOffsetMemory.description":
      "手动调整的歌词时间轴偏移会按歌曲保存，再次播放同一首歌时自动恢复。",
    "folia.releaseNotes.v0_5_27.posterWallSearch.title": "海报墙搜索与手势",
    "folia.releaseNotes.v0_5_27.posterWallSearch.description":
      "各海报墙页面现在支持列表搜索，也可以直接输入文字或使用搜索手势快速打开搜索。",
    "folia.releaseNotes.v0_6_0.intro": "以下是 0.6.0 版本的新功能与改进",
    "folia.releaseNotes.v0_6_0.localLibraryV2.title": "本地曲库 2.0",
    "folia.releaseNotes.v0_6_0.localLibraryV2.description":
      "本地音乐库全面更新，支持多文件夹、专辑与艺术家跳转、元数据整理和在线匹配。",
    "folia.releaseNotes.v0_6_0.entityEditing.title": "艺术家与专辑实体编辑",
    "folia.releaseNotes.v0_6_0.entityEditing.description":
      "可以修改展示名称、搜索并合并重复实体，或选择歌曲拆分到新的或已有的艺术家与专辑。",
    "folia.releaseNotes.v0_6_0.unifiedSearch.title": "统一搜索与队列",
    "folia.releaseNotes.v0_6_0.unifiedSearch.description":
      "搜索功能支持网易云、本地库、Navidrome多来源; 支持构建混合了在线歌曲与本地歌曲的播放队列。",
    "folia.releaseNotes.v0_6_0.metadataMatching.title": "海报墙增强",
    "folia.releaseNotes.v0_6_0.metadataMatching.description":
      "海报墙现在支持基于搜索来筛选歌曲并加入队列，优化了卡片加载动画",
    "folia.releaseNotes.v0_6_0.dailyRecommendations.title": "每日推荐",
    "folia.releaseNotes.v0_6_0.dailyRecommendations.description": "现在可以浏览网易云日推歌曲。",
    "folia.releaseNotes.v0_6_0.visualizerBackgrounds.title": "全新可视化背景系统",
    "folia.releaseNotes.v0_6_0.visualizerBackgrounds.description":
      "新增隐现与漫游背景，支持静态模式、字幕可读性背景、颜色来源和节拍响应，并统一了背景设置与命令。",
    "folia.releaseNotes.v0_6_0.dioramaRework.title": "镜台点云重构",
    "folia.releaseNotes.v0_6_0.dioramaRework.description":
      "镜台加入涟漪驱动的点云与长廊双模式、更多粒子形态、关键字着色和可调的粒子密度与辉光。",
    "folia.releaseNotes.v0_6_1.intro": "以下是 0.6.1 版本的新功能与改进",
    "folia.releaseNotes.v0_6_1.settingsRework.title": "设置页面重构",
    "folia.releaseNotes.v0_6_1.settingsRework.description":
      "全新重构的设置页面，结构更清晰、分类更合理，提供更舒适易用的配置体验。",
    "folia.releaseNotes.v0_6_1.autoHideChrome.title": "界面元素自动隐藏",
    "folia.releaseNotes.v0_6_1.autoHideChrome.description":
      "可自由调整是否在静止时自动隐藏顶部标题栏与播放页返回按键。",
    "folia.releaseNotes.v0_6_1.voiceInputPause.title": "语音输入自动暂停",
    "folia.releaseNotes.v0_6_1.voiceInputPause.description":
      "Windows 环境下支持在触发系统语音输入时自动暂停播放，可在实验室设置中开启。",
    "folia.releaseNotes.v0_6_1.obsStaticLink.title": "OBS 静态链接分享",
    "folia.releaseNotes.v0_6_1.obsStaticLink.description":
      "Web 版本支持导出与分享 OBS 静态串流链接，方便推流工具直接引用。",
    "folia.userGuide.title": "欢迎使用 Folia",
    "folia.userGuide.subtitle": "这里有一些提示，希望能帮到你。",
    "folia.userGuide.commandPalette.title": "命令面板",
    "folia.userGuide.commandPalette.desc":
      "在播放页面按下 S键 即可打开命令面板，快速访问功能与设置。",
    "folia.userGuide.typeToSearch.title": "全局搜索",
    "folia.userGuide.typeToSearch.desc":
      "在任意歌曲海报墙中按下任意字母或数字键，即可直接开始搜索当前列表。",
    "folia.userGuide.posterSearch.entryTitle": "从海报墙开始",
    "folia.userGuide.posterSearch.entryDesc":
      "当歌曲海报墙处于当前视图时，直接输入字母、数字或中文字符即可搜索当前列表。",
    "folia.userGuide.posterSearch.escapeTitle": "关闭搜索",
    "folia.userGuide.posterSearch.escapeDesc": "按下 Esc 可以关闭海报墙搜索面板。",
    "folia.userGuide.theme.title": "配色主题",
    "folia.userGuide.theme.desc": "可以手动定制亮色 / 暗色配色，也可以根据当前歌曲生成 AI 主题。",
    "folia.userGuide.theme.customDesc":
      "从视觉设置或命令面板打开 Theme Park，编辑并保存自定义亮色与暗色配色。",
    "folia.userGuide.theme.aiDesc":
      "配置 AI 主题设置后，Folia 可以根据歌曲生成配色，并可自动应用已缓存的歌曲主题。",
    "folia.userGuide.clickThrough.title": "点击穿透恢复",
    "folia.userGuide.clickThrough.desc":
      "开启点击穿透后，如果窗口控件被隐藏或不方便触达，可以通过系统托盘图标切换点击穿透。",
    "folia.userGuide.clickThrough.trayTitle": "使用托盘图标",
    "folia.userGuide.clickThrough.trayDesc":
      "右键点击 Folia 的系统托盘图标，在菜单中选择点击穿透选项，即可开启或关闭。",
    "folia.userGuide.clickThrough.lockTitle": "使用锁定按钮",
    "folia.userGuide.clickThrough.lockDesc":
      "也可以把鼠标移到顶部标题栏热点，唤出锁定按钮后点击关闭点击穿透。",
    "folia.userGuide.gotIt": "我知道了",
