    "folia.help.version": "版本",
    "folia.releaseNotes.v0_5_27.intro": "以下是 0.5.27 版本的新功能與改進",
    "folia.releaseNotes.v0_5_27.diorama.title": "Diorama「鏡臺」3D 歌詞模式",
    "folia.releaseNotes.v0_5_27.diorama.description":
      "歌詞化作空間中的 3D 文字，鏡頭沿路徑逐句飛行，並支持跟唱輝光、粒子與主題聯動。",
    "folia.releaseNotes.v0_5_27.lyricOffsetMemory.title": "時間軸偏移保存",
    "folia.releaseNotes.v0_5_27.lyricOffsetMemory.description":
      "手動調整的歌詞時間軸偏移會按歌曲保存，再次播放同一首歌時自動恢復。",
    "folia.releaseNotes.v0_5_27.posterWallSearch.title": "海報牆搜索與手勢",
    "folia.releaseNotes.v0_5_27.posterWallSearch.description":
      "各海報牆頁面現在支持列表搜索，也可以直接輸入文字或使用搜索手勢快速打開搜索。",
    "folia.releaseNotes.v0_6_0.intro": "以下是 0.6.0 版本的新功能與改進",
    "folia.releaseNotes.v0_6_0.localLibraryV2.title": "本地曲庫 2.0",
    "folia.releaseNotes.v0_6_0.localLibraryV2.description":
      "本地音樂庫全面更新，支持多文件夾、專輯與藝術家跳轉、元數據整理和在線匹配。",
    "folia.releaseNotes.v0_6_0.entityEditing.title": "藝術家與專輯實體編輯",
    "folia.releaseNotes.v0_6_0.entityEditing.description":
      "可以修改展示名稱、搜索併合並重復實體，或選擇歌曲拆分到新的或已有的藝術家與專輯。",
    "folia.releaseNotes.v0_6_0.unifiedSearch.title": "統一搜索與隊列",
    "folia.releaseNotes.v0_6_0.unifiedSearch.description":
      "搜索功能支持網易雲、本地庫、Navidrome多來源; 支持構建混合了在線歌曲與本地歌曲的播放隊列。",
    "folia.releaseNotes.v0_6_0.metadataMatching.title": "海報牆增強",
    "folia.releaseNotes.v0_6_0.metadataMatching.description":
      "海報牆現在支持基於搜索來篩選歌曲並加入隊列，優化了卡片加載動畫",
    "folia.releaseNotes.v0_6_0.dailyRecommendations.title": "每日推薦",
    "folia.releaseNotes.v0_6_0.dailyRecommendations.description": "現在可以瀏覽網易雲日推歌曲。",
    "folia.releaseNotes.v0_6_0.visualizerBackgrounds.title": "全新可視化背景系統",
    "folia.releaseNotes.v0_6_0.visualizerBackgrounds.description":
      "新增隱現與漫遊背景，支持靜態模式、字幕可讀性背景、顏色來源和節拍響應，並統一了背景設置與命令。",
    "folia.releaseNotes.v0_6_0.dioramaRework.title": "鏡臺點雲重構",
    "folia.releaseNotes.v0_6_0.dioramaRework.description":
      "鏡臺加入漣漪驅動的點雲與長廊雙模式、更多粒子形態、關鍵字著色和可調的粒子密度與輝光。",
    "folia.releaseNotes.v0_6_1.intro": "以下是 0.6.1 版本的新功能與改進",
    "folia.releaseNotes.v0_6_1.settingsRework.title": "設置頁面重構",
    "folia.releaseNotes.v0_6_1.settingsRework.description":
      "全新重構的設置頁面，結構更清晰、分類更合理，提供更舒適易用的配置體驗。",
    "folia.releaseNotes.v0_6_1.autoHideChrome.title": "界面元素自動隱藏",
    "folia.releaseNotes.v0_6_1.autoHideChrome.description":
      "可自由調整是否在靜止時自動隱藏頂部標題欄與播放頁返回按鍵。",
    "folia.releaseNotes.v0_6_1.voiceInputPause.title": "語音輸入自動暫停",
    "folia.releaseNotes.v0_6_1.voiceInputPause.description":
      "Windows 環境下支持在觸發系統語音輸入時自動暫停播放，可在實驗室設置中開啟。",
    "folia.releaseNotes.v0_6_1.obsStaticLink.title": "OBS 靜態鏈接分享",
    "folia.releaseNotes.v0_6_1.obsStaticLink.description":
      "Web 版本支持導出與分享 OBS 靜態串流鏈接，方便推流工具直接引用。",
    "folia.userGuide.title": "歡迎使用 Folia",
    "folia.userGuide.subtitle": "這裡有一些提示，希望能幫到你。",
    "folia.userGuide.commandPalette.title": "命令面板",
    "folia.userGuide.commandPalette.desc":
      "在播放頁面按下 S鍵 即可打開命令面板，快速訪問功能與設置。",
    "folia.userGuide.typeToSearch.title": "全局搜索",
    "folia.userGuide.typeToSearch.desc":
      "在任意歌曲海報牆中按下任意字母或數字鍵，即可直接開始搜索當前列表。",
    "folia.userGuide.posterSearch.entryTitle": "從海報牆開始",
    "folia.userGuide.posterSearch.entryDesc":
      "當歌曲海報牆處於當前視圖時，直接輸入字母、數字或中文字符即可搜索當前列表。",
    "folia.userGuide.posterSearch.escapeTitle": "關閉搜索",
    "folia.userGuide.posterSearch.escapeDesc": "按下 Esc 可以關閉海報牆搜索面板。",
    "folia.userGuide.theme.title": "配色主題",
    "folia.userGuide.theme.desc": "可以手動定製亮色 / 暗色配色，也可以根據當前歌曲生成 AI 主題。",
    "folia.userGuide.theme.customDesc":
      "從視覺設置或命令面板打開 Theme Park，編輯並保存自定義亮色與暗色配色。",
    "folia.userGuide.theme.aiDesc":
      "配置 AI 主題設置後，Folia 可以根據歌曲生成配色，並可自動應用已緩存的歌曲主題。",
    "folia.userGuide.clickThrough.title": "點擊穿透恢復",
    "folia.userGuide.clickThrough.desc":
      "開啟點擊穿透後，如果窗口控件被隱藏或不方便觸達，可以通過系統托盤圖標切換點擊穿透。",
    "folia.userGuide.clickThrough.trayTitle": "使用托盤圖標",
    "folia.userGuide.clickThrough.trayDesc":
      "右鍵點擊 Folia 的系統托盤圖標，在菜單中選擇點擊穿透選項，即可開啟或關閉。",
    "folia.userGuide.clickThrough.lockTitle": "使用鎖定按鈕",
    "folia.userGuide.clickThrough.lockDesc":
      "也可以把鼠標移到頂部標題欄熱點，喚出鎖定按鈕後點擊關閉點擊穿透。",
    "folia.userGuide.gotIt": "我知道了",
