    "folia.releaseNotes.v0_5_27.intro":
      "Here are the new features and improvements in version 0.5.27.",
    "folia.releaseNotes.v0_5_27.diorama.title": "Diorama 3D Lyrics Mode",
    "folia.releaseNotes.v0_5_27.diorama.description":
      "Lyrics become 3D text in space as the camera flies from line to line, with sing-along glow, particles, and theme-aware visuals.",
    "folia.releaseNotes.v0_5_27.lyricOffsetMemory.title": "Saved Timeline Offsets",
    "folia.releaseNotes.v0_5_27.lyricOffsetMemory.description":
      "Manual lyric timeline adjustments are saved per song and restored automatically the next time it plays.",
    "folia.releaseNotes.v0_5_27.posterWallSearch.title": "Poster-Wall Search and Gestures",
    "folia.releaseNotes.v0_5_27.posterWallSearch.description":
      "Poster-wall pages now support list search, direct typing, and a search gesture for quickly opening search.",
    "folia.releaseNotes.v0_6_0.intro":
      "Here are the new features and improvements in version 0.6.0.",
    "folia.releaseNotes.v0_6_0.localLibraryV2.title": "Local Library 2.0",
    "folia.releaseNotes.v0_6_0.localLibraryV2.description":
      "The local music library now uses a progressive poster-wall workflow for folders, albums, artists, and playlists, with stronger import, rescan, and cover-cache handling.",
    "folia.releaseNotes.v0_6_0.entityEditing.title": "Artist and Album Entity Editing",
    "folia.releaseNotes.v0_6_0.entityEditing.description":
      "Rename displayed identities, search and merge duplicates, or move selected songs into new or existing artist and album entities.",
    "folia.releaseNotes.v0_6_0.unifiedSearch.title": "Unified Search and Navigation",
    "folia.releaseNotes.v0_6_0.unifiedSearch.description":
      "The search workspace covers NetEase, local, Navidrome, and the current queue, while navigation history, map view, and detail links make browsing more continuous.",
    "folia.releaseNotes.v0_6_0.metadataMatching.title": "Smarter Metadata Matching",
    "folia.releaseNotes.v0_6_0.metadataMatching.description":
      "Local songs now have duration-assisted matching, batch metadata and cover organization, manual online matching, and reliable recovery of original local information.",
    "folia.releaseNotes.v0_6_0.dailyRecommendations.title":
      "Daily Recommendations and Playlist Editing",
    "folia.releaseNotes.v0_6_0.dailyRecommendations.description":
      "NetEase daily recommendations can be browsed, managed, and queued directly, and playlist editing now has smoother interaction feedback.",
    "folia.releaseNotes.v0_6_0.visualizerBackgrounds.title": "New Visualizer Background System",
    "folia.releaseNotes.v0_6_0.visualizerBackgrounds.description":
      "Latent and Nomand backgrounds add static mode, subtitle readability overlays, configurable color sources, beat response, and unified background settings and commands.",
    "folia.releaseNotes.v0_6_0.dioramaRework.title": "Diorama Particle Rework",
    "folia.releaseNotes.v0_6_0.dioramaRework.description":
      "Diorama now offers ripple-driven point-cloud and corridor modes, more particle shapes, keyword coloring, and controls for density and glow.",
    "folia.releaseNotes.v0_6_1.intro":
      "Here are the new features and improvements in version 0.6.1.",
    "folia.releaseNotes.v0_6_1.settingsRework.title": "Redesigned Settings Page",
    "folia.releaseNotes.v0_6_1.settingsRework.description":
      "A completely redesigned settings interface with cleaner structure, logical grouping, and improved usability.",
    "folia.releaseNotes.v0_6_1.autoHideChrome.title": "Auto-Hide Controls",
    "folia.releaseNotes.v0_6_1.autoHideChrome.description":
      "Optionally toggle auto-hiding for the top titlebar and player return button when idle.",
    "folia.releaseNotes.v0_6_1.voiceInputPause.title": "Voice Input Auto-Pause",
    "folia.releaseNotes.v0_6_1.voiceInputPause.description":
      "Automatically pause playback when using Windows voice typing, available in Lab Settings.",
    "folia.releaseNotes.v0_6_1.obsStaticLink.title": "OBS Static Link Sharing",
    "folia.releaseNotes.v0_6_1.obsStaticLink.description":
      "Web version now supports generating and sharing static OBS overlay links for streaming setups.",
