    "folia.aiHelp.importJsonTitle": "2. Paste JSON Result",
    "folia.aiHelp.prompt":
      "I am using the folia-major music player on GitHub and need help with a problem.\n\nFolia Guide: {{guideUrl}}\nFolia repository: {{repoUrl}}\n\nPlease use these references as context, then help me understand and solve the problem I describe next. If any information is missing, ask what I should provide before making uncertain assumptions.",
